<script setup lang="ts">
import { reactive, ref } from 'vue'
import { sendContactMessage } from '../services/api'
const form = reactive({ name: '', email: '', message: '' }); const sent = ref(false); const errorMessage = ref(''); const isSending = ref(false)
async function submit() { isSending.value = true; errorMessage.value = ''; try { await sendContactMessage(form); sent.value = true } catch (error) { errorMessage.value = error instanceof Error ? error.message : 'Kunde inte skicka meddelandet.' } finally { isSending.value = false } }
</script>
<template>
  <main class="mx-auto grid max-w-6xl gap-12 px-6 py-16 lg:grid-cols-[.8fr_1.2fr] lg:px-12"><section><p class="text-xs font-bold uppercase tracking-[.2em] text-[#6f8067]">Kontakt</p><h1 class="mt-4 font-serif text-6xl leading-none tracking-tight text-[#26352f]">Vi lyssnar.</h1><p class="mt-6 max-w-sm leading-7 text-[#718078]">Har du en fråga, idé eller hittat något som kan bli bättre? Skriv till oss.</p></section><form v-if="!sent" class="grid gap-5 border border-[#26352f]/15 bg-[#fffdf8] p-6 md:p-10" @submit.prevent="submit"><label class="grid gap-2 text-sm font-bold text-[#26352f]">Namn<input v-model="form.name" required class="border border-[#26352f]/20 bg-transparent p-3 font-normal outline-none focus:border-[#c16e4b]" /></label><label class="grid gap-2 text-sm font-bold text-[#26352f]">E-post<input v-model="form.email" type="email" required class="border border-[#26352f]/20 bg-transparent p-3 font-normal outline-none focus:border-[#c16e4b]" /></label><label class="grid gap-2 text-sm font-bold text-[#26352f]">Meddelande<textarea v-model="form.message" required rows="6" class="border border-[#26352f]/20 bg-transparent p-3 font-normal outline-none focus:border-[#c16e4b]"></textarea></label><p v-if="errorMessage" class="text-sm text-[#a64d3c]">{{ errorMessage }}</p><button class="button button--dark w-fit" type="submit" :disabled="isSending">{{ isSending ? 'Skickar...' : 'Skicka meddelande' }} <span aria-hidden="true">→</span></button></form><div v-else class="border border-[#26352f]/15 bg-[#d9e5d5] p-10"><h2 class="font-serif text-4xl text-[#26352f]">Tack för ditt meddelande.</h2><p class="mt-4 text-[#718078]">Vi återkommer så snart vi kan.</p></div></main>
</template>